    with open(cp_path) as f:
        cp = json.load(f)
    if isinstance(cp, dict):
        print(f'checkpoint keys ({len(cp)}): {sorted(cp.keys())}')
    elif isinstance(cp, list):
        ids = set()
        for entry in cp:
            if isinstance(entry, dict):
